INSERT INTO `support_quick_responses` (`id`, `title`, `content`, `category`, `created_by`, `is_public`, `usage_count`, `created_at`, `updated_at`) VALUES
(1, 'Welcome Message', 'Thank you for contacting support! We\'ve received your request and will respond shortly.', 'general', 1, 1, 0, '2025-09-24 06:56:45', '2025-09-24 06:56:45'),
(2, 'Request More Info', 'Thank you for your message. To better assist you, could you please provide more details about the issue you\'re experiencing?', 'general', 1, 1, 0, '2025-09-24 06:56:45', '2025-09-24 06:56:45'),
(3, 'Issue Resolved', 'Great! I\'m glad we could resolve your issue. If you have any other questions, please don\'t hesitate to reach out.', 'resolution', 1, 1, 0, '2025-09-24 06:56:45', '2025-09-24 06:56:45'),
(4, 'Escalating to Technical Team', 'I\'m escalating your issue to our technical team for further investigation. You should hear back from us within 24 hours.', 'escalation', 1, 1, 0, '2025-09-24 06:56:45', '2025-09-24 06:56:45'),
(5, 'Account Issue', 'I see you\'re having an account-related issue. Let me look into this for you right away.', 'account', 1, 1, 0, '2025-09-24 06:56:45', '2025-09-24 06:56:45'),
(6, 'Billing Question', 'Thank you for your billing inquiry. I\'ll review your account and get back to you with the details.', 'billing', 1, 1, 0, '2025-09-24 06:56:45', '2025-09-24 06:56:45');
