CREATE DEFINER=`root`@`localhost` PROCEDURE `school_applicants` (IN `in_id` VARCHAR(100), IN `query_type` VARCHAR(100), IN `in_upload` VARCHAR(300), IN `in_type_of_application` VARCHAR(100), IN `in_name_of_applicant` VARCHAR(100), IN `in_home_address` VARCHAR(100), IN `in_date_of_birth` VARCHAR(100), IN `in_sex` VARCHAR(100), IN `in_religion` VARCHAR(100), IN `in_tribe` VARCHAR(100), IN `in_school_attended` VARCHAR(100), IN `in_class1` VARCHAR(100), IN `in_state_of_origin` VARCHAR(100), IN `in_l_g_a` VARCHAR(100), IN `in_nationality` VARCHAR(100), IN `in_time` VARCHAR(100), IN `in_venue` VARCHAR(100), IN `in_common_entrance` VARCHAR(100), IN `in_placement` VARCHAR(100), IN `in_examination_date` DATE, IN `in_date` VARCHAR(100), IN `in_first_name` VARCHAR(100), IN `in_examination_number` VARCHAR(100), IN `in_father_name` VARCHAR(100), IN `in_state_of_origin1` VARCHAR(100), IN `in_address` VARCHAR(100), IN `in_school` VARCHAR(100), IN `in_examination_number1` VARCHAR(100), IN `in_name1` VARCHAR(100), IN `in_mother_name` VARCHAR(100), IN `in_state_of_origin3` VARCHAR(100), IN `in_state_of_origin2` VARCHAR(100), IN `in_home_address1` VARCHAR(100), IN `in_office_marker_address` VARCHAR(100), IN `in_telephone_address` VARCHAR(100), IN `in_other_score` INT(10), IN `in_venue1` VARCHAR(100), IN `in_image` TEXT, IN `in_mathematics` INT(11), IN `in_english` INT(11), IN `in_others` VARCHAR(100), IN `in_admission_no` VARCHAR(100), IN `in_last_school_atterded` VARCHAR(100), IN `in_special_health_needs` VARCHAR(100), IN `in_date_of_birth1` VARCHAR(100), IN `in_father_place_of_work` VARCHAR(100), IN `in_father_occapation` VARCHAR(100), IN `in_blood_group` VARCHAR(100), IN `in_academic_year` VARCHAR(100), IN `in_admission_date` DATE, IN `in_roll_number` INT(100), IN `in_status` VARCHAR(100), IN `in_section` VARCHAR(100), IN `in_house` VARCHAR(100), IN `in_category` VARCHAR(100), IN `in_primary_contact_number` VARCHAR(100), IN `in_caste` VARCHAR(100), IN `in_mother_tongue` VARCHAR(100), IN `in_language_known` VARCHAR(100), IN `in_application_no` VARCHAR(100), IN `in_admission_year` VARCHAR(100), IN `in_class_type` VARCHAR(100), IN `in_current_class` VARCHAR(100), IN `in_medical_condition` VARCHAR(100), IN `in_upload_transfer_certificate` VARCHAR(100), IN `in_school_id` INT(6))   BEGIN 
